"""
loganalyse.py: Apache-style log analyser with sessionisation, top pages, error rates per hour, and bot detection.

* Reads settings from config.json
* Parses Apache-style access logs (CLF/combined format)
* Groups requests into sessions by IP and time gap
* Computes top N pages, error rates (client/server), and per-hour metrics
* Applies bot detection heuristics

Requires: Python 3.x (no external deps)
"""
import sys
import re
import json
import collections
from datetime import datetime, timedelta
from collections import defaultdict, Counter
import os

LOG_PATTERN = re.compile(r'^(?P<ip>\S+) \S+ \S+ \[(?P<time>[^\]]+)\] "(?P<request>[^"]*)" (?P<status>\d{3}) (?P<size>\S+) "[^"]*" "(?P<ua>[^"]*)"')

class Config:
    """Class to manage config loading and defaults."""
    def __init__(self, path):
        with open(path) as f:
            self.data = json.load(f)
    def __getitem__(self, k):
        return self.data[k]
    def get(self, k, defv=None):
        return self.data.get(k, defv)

def parse_log_line(line, config):
    """Parse a single log line, returning dict or None."""
    m = LOG_PATTERN.match(line)
    if not m:
        return None
    try:
        t = datetime.strptime(m.group('time'), config['parse_time_format'])
    except Exception:
        return None
    req = m.group('request').split()
    method, url, proto = req if len(req) == 3 else (req[0], '', '')
    return {
        'ip': m.group('ip'),
        'time': t,
        'method': method,
        'url': url,
        'status': int(m.group('status')),
        'size': int(m.group('size')) if m.group('size').isdigit() else 0,
        'ua': m.group('ua'),
    }

class SessionManager:
    """Handle sessionisation by IP and time gap."""
    def __init__(self, config):
        self.config = config
        self.sessions = defaultdict(list)
        self.timeout = timedelta(minutes=self.config['session_timeout_minutes'])
    def add(self, rec):
        ip = rec['ip']
        cur_sessions = self.sessions[ip]
        if not cur_sessions:
            cur_sessions.append([rec])
            return
        last_session = cur_sessions[-1]
        if rec['time'] - last_session[-1]['time'] <= self.timeout:
            last_session.append(rec)
        else:
            cur_sessions.append([rec])
    def all_sessions(self):
        """Yield per-ip sessions (list of lists of records)."""
        for ip, session_lists in self.sessions.items():
            for sess in session_lists:
                if len(sess) >= self.config['min_session_requests']:
                    yield (ip, sess)

class HourlyStats:
    """Gather stats per hour chunk."""
    def __init__(self, config):
        self.config = config
        self.data = defaultdict(lambda: {'total':0,'errors':0})
        self.chunk = timedelta(minutes=self.config['hourly_chunk_minutes'])
    def add(self, rec):
        hour_key = rec['time'].replace(minute=0, second=0, microsecond=0)
        self.data[hour_key]['total'] += 1
        if rec['status'] in self.config['status_codes_client_error']+self.config['status_codes_server_error']:
            self.data[hour_key]['errors'] += 1
    def report(self):
        lines = []
        for h in sorted(self.data.keys()):
            tot = self.data[h]['total']
            err = self.data[h]['errors']
            rate = err/tot if tot else 0.0
            lines.append(f"{h}: {tot} reqs, {err} errors, error rate {rate:.2%}")
        return lines

def detect_bot(ip, sessions, config):
    """Heuristic bot detection."""
    # Known UA substring
    for sess in sessions:
        for rec in sess:
            for bot_substr in config['known_bots']:
                if bot_substr.lower() in rec['ua'].lower():
                    return True
    # Too many sessions per IP
    if len(sessions) >= config['bot_min_sessions']:
        return True
    # Short avg inter-request interval
    total_rqs = sum(len(sess) for sess in sessions)
    times = [r['time'] for sess in sessions for r in sess]
    if len(times) > 1:
        total_time = (max(times)-min(times)).total_seconds()
        avg_gap = total_time/max(1, total_rqs-1)
        if avg_gap < config['bot_max_avg_interval']:
            return True
    return False

def main():
    if len(sys.argv)<2:
        print("USAGE: python loganalyse.py logfile.log", file=sys.stderr)
        sys.exit(1)
    conf = Config('config.json')
    fname = sys.argv[1]
    sessioner = SessionManager(conf)
    hourly = HourlyStats(conf)
    page_counter = Counter()
    bot_ips = set()
    err_lines = 0
    total_lines = 0

    with open(fname) as f:
        for line in f:
            total_lines += 1
            rec = parse_log_line(line, conf)
            if not rec:
                err_lines += 1
                continue
            if rec['url'] in conf['ignore_pages'] or (conf.get('validate_status',True) and rec['status']==0):
                continue
            sessioner.add(rec)
            page_counter[rec['url']] += 1
            hourly.add(rec)
    # Session post-processing
    ip_sessions = defaultdict(list)
    for ip, sess in sessioner.all_sessions():
        ip_sessions[ip].append(sess)
    # Bot detection
    for ip, sessions in ip_sessions.items():
        if detect_bot(ip, sessions, conf):
            bot_ips.add(ip)
    # Output
    print(f"Log parsed: {total_lines} lines; errors/skipped: {err_lines}")
    print(f"Active IPs: {len(ip_sessions)} | Bots detected: {len(bot_ips)}")
    print("\nTop pages:")
    for url, cnt in page_counter.most_common(conf['top_pages_count']):
        print(f"{url:40} {cnt}")
    print("\nHourly error rates:")
    for line in hourly.report():
        print(line)
    print("\nTop bot IPs:")
    for ip in list(bot_ips)[:10]:
        print(ip)
    # Print example of session if configured
    if conf.get('output_full_sessions'):
        for ip, sessions in list(ip_sessions.items())[:2]:
            print(f"\nIP: {ip}")
            for sess in sessions:
                print(f"  Session from {sess[0]['time']} with {len(sess)} reqs")
EOF

